import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Project X","text":"Xray-core","tagline":"Не бойтесь облаков, застилающих вид – золотые глаза, словно факел, озаряют небо.","image":{"src":"/img-project-x.png","alt":"Xray, Penetrates Everything"},"actions":[{"theme":"brand","text":"Первые шаги","link":"/ru/document/"},{"theme":"alt","text":"Руководство по конфигурации","link":"/ru/config/"},{"theme":"alt","text":"Sponsor & Donation & NFTs","link":"/ru/about/sponsor.md"}]},"features":[{"title":"Оригинальные протоколы","icon":"📄","details":"Оригинальные протоколы VLESS, XTLS, XUDP, XHTTP, REALITY и другие охватывают проксирование, управление потоком, мультиплексирование, транспорт и безопасность."},{"title":"Мощная маршрутизация","icon":"🔀","details":"Гибкая система маршрутизации и DNS поддерживает тонкую настройку трафика по доменам, IP, портам, протоколам, процессам, пользователям и другим условиям."},{"title":"Маскировка трафика","icon":"🎭","details":"VLESS fallback, REALITY, управление потоком XTLS, FinalMask и другие подходы снижают заметность трафика и повышают устойчивость к обнаружению на нескольких уровнях."},{"title":"Свободная комбинация","icon":"🧩","details":"Прокси-протоколы, режимы управления потоком, транспортные уровни и система маршрутизации свободно комбинируются под разные сценарии."},{"title":"Сверхнизкое потребление ресурсов","icon":"📊","details":"VLESS избавляется от избыточного шифрования, а Splice снижает накладные расходы на пересылку, поэтому Xray подходит даже для OpenWRT, Raspberry Pi и других маломощных устройств."},{"title":"Сообщество","icon":"💖","details":"Активные обсуждения и вклад сообщества, лицензия с открытым исходным кодом MPL 2.0."}]},"headers":[],"relativePath":"ru/index.md","filePath":"ru/index.md","lastUpdated":1778396361000}`),a={name:`ru/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h2 id="xtls-xray-v2ray" tabindex="-1">XTLS? Xray? V2Ray? <a class="header-anchor" href="#xtls-xray-v2ray" aria-label="Permalink to “XTLS? Xray? V2Ray?”">​</a></h2><blockquote><p><strong>XTLS — это блестящая идея для TLS, которую мы изучаем, в то время как Xray — это лучшая практика, которую мы поддерживаем.</strong></p></blockquote><ul><li>Xray-core изначально вырос из v2ray-core, но уже давно развивается самостоятельно, поэтому его больше не стоит считать полностью совместимой заменой v2ray-core. <ul><li>Только один исполняемый файл, включающий функциональность ctl, команда run используется по умолчанию.</li><li>Часть структуры конфигурации и привычных способов использования похожа на v2ray-core, но переменные среды, префиксы API и многие возможности уже отличаются.</li><li>Открытый raw протокол ReadV на всех платформах.</li><li>Полная поддержка VLESS, XTLS Vision и REALITY.</li><li>Доступно несколько режимов управления потоком XTLS, а в подходящих сценариях вместе со Splice это дает очень высокую производительность.</li></ul></li></ul><h3 id="кто-мы" tabindex="-1">Кто мы? <a class="header-anchor" href="#кто-мы" aria-label="Permalink to “Кто мы?”">​</a></h3><blockquote><p><strong>Неважно, кто мы. Важно то, что мы будем продолжать двигаться вперед и никогда не оглядываться назад.</strong></p></blockquote><h3 id="помогите-xray-стать-сильнее" tabindex="-1">Помогите Xray стать сильнее <a class="header-anchor" href="#помогите-xray-стать-сильнее" aria-label="Permalink to “Помогите Xray стать сильнее”">​</a></h3><p>Мы будем рады вашей помощи в развитии Xray!</p><ul><li>🖥️ Помогите в разработке и тестировании Xray, отправляйте качественные запросы на включение (Pull Request).</li><li>📩 Создавайте конструктивные или важные задачи и обсуждения в <a href="https://github.com/XTLS/Xray-core/issues" target="_blank" rel="noreferrer">GitHub Issues</a> или <a href="https://github.com/XTLS/Xray-core/discussions" target="_blank" rel="noreferrer">Discussion area</a>.</li><li>📝 Поделитесь своим опытом использования и отправьте его на <a href="https://github.com/XTLS/Xray-docs-next" target="_blank" rel="noreferrer">сайт документации</a> Xray.</li><li>💬 Помогите участникам группы / общайтесь в группе Telegram.</li><li><strong>... На самом деле, любая поддержка Xray сделает его сильнее.</strong></li></ul><h3 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to “Telegram”">​</a></h3><ul><li><p><a href="https://t.me/projectXray" target="_blank" rel="noreferrer">Группа обсуждения Project X</a></p><ul><li>Группа для пользователей на китайском и английском языках. Основная группа общения.</li></ul></li><li><p><a href="https://t.me/projectVless" target="_blank" rel="noreferrer">Project VLESS Group</a></p><ul><li>Группа для русскоязычных пользователей. Сестринская группа <a href="https://t.me/projectXray" target="_blank" rel="noreferrer">Project X</a>.</li></ul></li><li><p><a href="https://t.me/projectXHTTP" target="_blank" rel="noreferrer">Project XHTTP Group</a></p><ul><li>Группа для пользователей на персидском языке. Сестринская группа <a href="https://t.me/projectXray" target="_blank" rel="noreferrer">Project X</a>.</li></ul></li><li><p><a href="https://t.me/projectXtls" target="_blank" rel="noreferrer">Канал Project X</a></p><ul><li>Публикация последних новостей о Project X.</li></ul></li></ul><h3 id="благодарности" tabindex="-1">Благодарности <a class="header-anchor" href="#благодарности" aria-label="Permalink to “Благодарности”">​</a></h3><ul><li>Спасибо всем за вашу поддержку!</li><li>Спасибо создателям всевозможных скриптов, образов Docker, клиентам... Спасибо всем, кто помогает улучшать экосистему!</li><li>Спасибо всем, кто вносит свой вклад в веб-сайт и документацию Xray.</li><li>Спасибо всем, кто высказывает ценные предложения и замечания.</li><li>Спасибо каждому участнику группы Telegram, который помогает другим.</li></ul><h3 id="подробнее-о-project-x" tabindex="-1">Подробнее о Project X <a class="header-anchor" href="#подробнее-о-project-x" aria-label="Permalink to “Подробнее о Project X”">​</a></h3><ul><li>Если вы хотите узнать больше об истории и развитии Project X, нажмите <a href="./about/news.html">здесь</a></li><li>Проект X теперь выпускает NFT! Если вы хотите получить NFT Project X, либо пожертвовать или спонсировать Project X, нажмите <a href="https://github.com/XTLS/Xray-core/discussions/3633" target="_blank" rel="noreferrer">здесь</a></li></ul><h3 id="лицензия" tabindex="-1">Лицензия <a class="header-anchor" href="#лицензия" aria-label="Permalink to “Лицензия”">​</a></h3><p><a href="https://github.com/XTLS/Xray-core/blob/main/LICENSE" target="_blank" rel="noreferrer">Mozilla Public License Version 2.0</a></p><h3 id="динамика-звезд-на-github" tabindex="-1">Динамика звезд на GitHub <a class="header-anchor" href="#динамика-звезд-на-github" aria-label="Permalink to “Динамика звезд на GitHub”">​</a></h3><p><a href="https://starchart.cc/XTLS/Xray-core" target="_blank" rel="noreferrer"><img src="https://starchart.cc/XTLS/Xray-core.svg?variant=adaptive" alt="Stargazers over time"></a></p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};